/**
 * Fetches a resource from the provided URL with a retry mechanism.
 * 
 * @param {string} url - The URL to fetch.
 * @param {number} [retries=3] - The maximum number of retry attempts after the initial failure.
 * @param {number} [delayMs=500] - The delay in milliseconds between retry attempts.
 * @returns {Promise<Response>} A promise that resolves to the Response object.
 * @throws {Error} Throws the last encountered error if all retry attempts fail.
 */
export async function fetchWithRetry(url: string, retries = 3, delayMs = 500): Promise<Response> {
  for (let i = 0; i <= retries; i++) {
    try { return await fetch(url); } catch (e) { if (i === retries) throw e; await new Promise(r => setTimeout(r, delayMs)); }
  }
  throw new Error('unreachable');
}
```

